local _rawSession = getgenv()._X_AUTH_SESSION
getgenv()._X_AUTH_SESSION = nil
getgenv()._X_AUTH_TOKEN = nil

local function _deny(reason)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "❌ ACCESS DENIED",
            Text = "Direct execution blocked! (" .. tostring(reason) .. ") Please execute via Loader.lua",
            Duration = 6
        })
    end)
    warn("[X SUITE] Security Alert: " .. tostring(reason) .. " - Direct loadstring blocked!")
end

if type(_rawSession) ~= "table" then
    _deny("Missing Auth Session")
    return
end

local _expectedTier = "pro"
local _currentTier = string.lower(tostring(_rawSession.Tier or ""))
if _currentTier ~= _expectedTier and not string.find(_currentTier, _expectedTier) and not (_currentTier == "titan") then
    _deny("Tier Mismatch: Session bound to " .. tostring(_rawSession.Tier))
    return
end

local _ts = tonumber(_rawSession.Timestamp)
local _k = tostring(_rawSession.Key or "")
local _h = tostring(_rawSession.HWID or "")
local _n = tostring(_rawSession.Nonce or "")
local _sig = tostring(_rawSession.Signature or "")

local _now = math.floor(tick())
if not _ts or math.abs(_now - _ts) > 30 then
    _deny("Session Expired")
    return
end

local function _hash(s)
    local h = 5381
    for i = 1, #s do
        h = ((h * 33) + string.byte(s, i)) % 2147483647
    end
    return string.format("%08x", h)
end

local _expectedSig = _hash(tostring(_ts) .. ":" .. _k .. ":" .. _h .. ":" .. _n .. ":" .. tostring(_rawSession.Tier) .. ":" .. (_rawSession.IsPlus and "1" or "0") .. ":" .. (_rawSession.IsFounder and "1" or "0") .. ":" .. (_rawSession.IsSeller and "1" or "0") .. ":XT7789_NEXUS_SECURITY_SALT_2026")
if _sig ~= _expectedSig then
    _deny("Invalid or Tampered Session Signature")
    return
end

-- CRYPTOGRAPHIC IN-MEMORY STREAM KEY FROM VERIFIED AUTHENTICATOR
local _0xK = _rawSession.StreamKey
if type(_0xK) ~= "table" or #_0xK == 0 then
    _deny("Missing Cryptographic Stream Key")
    return
end

